func (this *Accessible) Get_states(pStates int64) int32 {
	if this.control != (nil) && this.control.IsDisposed() {
		return win32.COMCO_E_OBJNOTCONNECTED
	}
	var event *AccessibleControlEvent = NewAccessibleControlEvent(this)
	event.ChildID = ACCCHILDID_SELF
	for i := int32(0); i < this.AccessibleControlListenersSize(); i++ {
		var listener AccessibleControlListener = jrt.Cast[AccessibleControlListener](this.accessibleControlListeners.Get(i))
		listener.GetState(event)
	}
	var states int32 = event.Detail
	var ia2States int32 = 0
	if (states & ACCSTATE_ACTIVE) != 0 {
		ia2States |= win32.COMIA2_STATE_ACTIVE
	}
	if (states & ACCSTATE_SINGLELINE) != 0 {
		ia2States |= win32.COMIA2_STATE_SINGLE_LINE
	}
	if (states & ACCSTATE_MULTILINE) != 0 {
		ia2States |= win32.COMIA2_STATE_MULTI_LINE
	}
	if (states & ACCSTATE_REQUIRED) != 0 {
		ia2States |= win32.COMIA2_STATE_REQUIRED
	}
	if (states & ACCSTATE_INVALID_ENTRY) != 0 {
		ia2States |= win32.COMIA2_STATE_INVALID_ENTRY
	}
	if (states & ACCSTATE_SUPPORTS_AUTOCOMPLETION) != 0 {
		ia2States |= win32.COMIA2_STATE_SUPPORTS_AUTOCOMPLETION
	}
	if this.GetRole() == ACCROLE_TEXT && this.AccessibleTextExtendedListenersSize() > 0 {
		ia2States |= win32.COMIA2_STATE_EDITABLE
	}
	if AccessibleDEBUG {
		AccessiblePrint(fmt.Sprintf("%v.IAccessible2::get_states returning%s%s", this, this.GetIA2StatesString(ia2States), this.Hresult(win32.COMS_OK)))
	}
	win32.OSMoveMemoryOverload13(pStates, []int32{ia2States}, 4)
	return win32.COMS_OK
}

